import {mock} from 'node:test';
import assert from 'node:assert/strict';
import {fixtureReceipt,fixtureRow,loadPublicFixtureImages} from '../../e2e/fixtures/834-server-data.mjs';
const [mode='full',denied]=process.argv.slice(2),images=await loadPublicFixtureImages();let stock=14,dbReads=0,bridgeReads=0,imageReads=0,rpcReads=0;
process.env.STOCK_SQL_BRIDGE_URL='https://834-fixture.invalid';process.env.STOCK_SQL_BRIDGE_KEY='not-a-credential';
globalThis.fetch=async(url,options)=>{if(String(url)==='https://834-fixture.invalid/stmast'){bridgeReads++;assert.equal(options.method,'POST');assert.deepEqual(JSON.parse(options.body),{sku:'8-34'});return Response.json({row:{CODE:'8-34',DESCR:'XMAS 6CM BALLS 10PC TUBE',UNITS:'10PC',PRICE_A:31.30,ONHAND:stock,BOOKED:0}});}const view=fixtureReceipt.views.find(v=>v.image.url===url);assert.ok(view,'Only exact public URLs may be read');imageReads++;assert.equal(options.redirect,'error');return new Response(images.get(view.id),{headers:{'content-type':'image/jpeg'}});};
const raw={...fixtureRow,title:'CHRISTMAS BAUBLES | 6CM | 10PC TUBE',original_description:'XMAS 6CM BALLS 10PC TUBE',price:36,stock_qty:61,available_stock:61,category:'Party, Events & Seasonals',subcategory_one:'Party Décor',created_at:'2026-01-01T00:00:00Z',updated_at:'2026-01-01T00:00:00Z'},before=JSON.stringify(raw);
const client={from(table){dbReads++;assert.ok(['website_stock','products'].includes(table));let columns;const q={select(value){columns=value;return q;},range(){return q;},order(){return q;},limit(){return q;},eq(){return q;},in(){return q;},or(){return q;},then(yes,no){return Promise.resolve({data:table==='products'?[]:columns==='updated_at'?[{updated_at:raw.updated_at}]:[raw],count:1,error:null}).then(yes,no);}};return q;},rpc:async(name,args)=>{rpcReads++;assert.equal(name,'loader_834_public_family_read_v1');assert.deepEqual(args,{p_body:{sku:'8-34',destination:'website'}});return {data:structuredClone(fixtureReceipt),error:null};}};
mock.module('../../lib/stock-supabase.mjs',{namedExports:{createStockClient:()=>client}});
mock.module('../../api/_auth.js',{namedExports:{requireApprovedCustomer:async(_req,res)=>{if(denied){res.status(401).json({error:'denied'});return null;}return{id:'synthetic-approved'};}}});
mock.module('../../api/_site-config.js',{namedExports:{readSiteConfigJson:async name=>name==='taxonomy/categories.json'?[{id:'party-events-seasonals',label:'Party, Events & Seasonals',children:[{id:'party-decor',label:'Party Décor',children:[]}]}]:null}});
mock.module('../../api/_placements.js',{namedExports:{loadPlacementMapIfEnabled:async()=>null,skusMatchingBrowsePath:()=>[]}});
mock.module('../../api/_groups.js',{namedExports:{loadGroupInfoMapIfEnabled:async()=>null}});
mock.module('../../api/_product-availability.js',{namedExports:{availabilityForRow:row=>({state:'in_stock',canOrder:true,stockQty:row.stock_qty}),loadIncomingAvailabilityMap:async()=>new Map(),loadIncomingAvailabilityVersion:async()=>({newest:'0',count:0})}});
const {default:handler}=await import('../../api/products.js');const query=mode==='full'?{}:mode==='skus'?{skus:'8-34'}:mode==='browse'?{browsePath:'party-events-seasonals/party-decor'}:{identifier:'8-34-SIL'};
const response=()=>({headers:{},setHeader(k,v){this.headers[k]=v;},status(n){this.code=n;return this;},json(v){this.body=v;return this;},end(){return this;}});let res=response();await handler({method:'GET',headers:{},query},res);
if(denied){assert.equal(res.code,401);assert.deepEqual([dbReads,bridgeReads,imageReads,rpcReads],[0,0,0,0]);}else{assert.equal(res.code,200);assert.equal(res.body.length,1);assert.equal(res.body[0].stockQty,14);assert.equal(res.body[0].price,36);assert.equal(res.body[0].unitsOfIssue,'10PC');assert.equal(res.body[0].images.length,6);assert.equal(res.body[0].image,fixtureReceipt.views[0].image.url);assert.equal(rpcReads,1);assert.equal(imageReads,6);if(mode==='full'){stock=2;res=response();await handler({method:'GET',headers:{},query},res);assert.equal(res.body[0].stockQty,2,'Warm cached canonical row still requires fresh source');assert.equal(rpcReads,2);stock=0;res=response();await handler({method:'GET',headers:{},query},res);assert.deepEqual(res.body,[]);}}
assert.equal(JSON.stringify(raw),before);console.log(JSON.stringify({passed:true,mode,denied:!!denied,dbReads,bridgeReads,imageReads,rpcReads}));
